insert into public.questions (
  id, question_text, option_a, option_b, option_c, option_d,
  correct_option, explanation, category, difficulty
) values
  ('9ddb7468-a94f-54ee-9de1-4bb6a396a23d', 'Una paciente de 26 años, a las 7 horas posparto, refiere baja producción de leche materna y se muestra preocupada por el crecimiento y desarrollo de su bebé. ¿Qué actividad de enfermería debe realizarse de inmediato?', 'Educar fomentando una buena succión y lactancia materna exclusiva a libre demanda.', 'Educar fomentando una alimentación complementaria a libre demanda.', 'Educar fomentando el uso de fórmula y alimentación complementaria.', 'Educar fomentando la succión y lactancia materna exclusiva con horarios.', 'A', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'CACES Octubre 2026 - revisión A'),
  ('a54dda45-ece4-51b3-8084-dfbf00a7fea8', 'Después de tomar los signos vitales de un paciente hospitalizado, el profesional de enfermería tiene las manos visiblemente limpias y elige un preparado de base alcohólica para realizar la higiene de manos. ¿Cuánto debe durar el procedimiento?', 'De 50 a 60 segundos.', 'De 20 a 30 segundos.', 'De 10 a 15 segundos.', 'De 40 a 60 segundos.', 'B', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado y Procedimientos Clínicos de Enfermería', 'CACES Octubre 2026 - revisión A'),
  ('c153d5ae-67eb-5343-9957-17d56cf37db6', 'Un paciente de 80 años hospitalizado, con signos de demencia, se retira una vía periférica. El personal de enfermería canaliza una nueva vía en el miembro contrario para continuar la hidratación. Según el protocolo de higiene de manos, ¿qué producto debe utilizar inmediatamente después del procedimiento?', 'Amonio cuaternario.', 'Hipoclorito de sodio al 10%.', 'Preparado de base alcohólica.', 'Monopersulfato de sodio.', 'C', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado y Procedimientos Clínicos de Enfermería', 'CACES Octubre 2026 - revisión A'),
  ('1ad6087f-b854-561b-b1c4-e9458fe3e65f', 'Paciente de 79 años, con patología cardiaca, lleva insertada válvula de derivación ventrículo-peritoneal, presenta dificultad para respirar, frecuencia respiratoria 24 por minuto y limitación del esfuerzo terapéutico. Los familiares plantean la posibilidad de solicitar alta a petición. ¿Cuál es el diagnóstico de enfermería más probable para el abordaje de la condición clínica del paciente?', 'Manejo ineficaz del régimen terapéutico personal r/c la complejidad del tratamiento m/p datos clínicos evidentes, inseguridad y ansiedad acerca de su vida futura.', 'Patrón respiratorio ineficaz r/c desequilibrio en la ventilación perfusión m/p dolor corporal y somnolencia.', 'Déficit de conocimientos r/c su situación actual de salud m/p apatía a la información, desapego e incumplimiento en el tratamiento.', 'Alteración del intercambio gaseoso r/c desequilibrio en la ventilación perfusión m/p disnea y taquipnea.', 'D', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidados del Adulto y Adulto Mayor', 'CACES Octubre 2026 - revisión A'),
  ('000633d6-de79-50e7-9ebd-27d64dc3a2c1', '¿Cuál es la posición indicada para realizar una intubación endotraqueal?', 'Roser o Proetz.', 'Trendelenburg.', 'Posición de Kraske.', 'Decúbito supino o dorsal.', 'A', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado y Procedimientos Clínicos de Enfermería', 'CACES Octubre 2026 - revisión A'),
  ('8d5d0c1b-5a41-501f-842b-9af325817f2c', 'Usted está analizando un brote de enfermedad diarreica aguda en los miembros de una familia. Los principales síntomas presentados son fiebre y deposiciones líquidas de color blanquecino. Se ha identificado el mismo agente causal en la mayoría de los casos; sin embargo, uno de los miembros de la familia presenta solo dificultad para orinar y dolor abdominal, no se ha detectado la presencia del agente causal de la enfermedad en los exámenes de laboratorio. ¿Cómo clasifica este último caso?', 'Caso autóctono.', 'Caso descartado.', 'Caso Índice.', 'Caso probable.', 'B', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'CACES Octubre 2026 - revisión A'),
  ('39798b16-7fa7-58c3-b7f3-29cb5c0ef692', '¿Qué vacunas le corresponden administrar a un niño de 6 meses?', 'Varicela, SRP, Fiebre amarilla.', 'Vacuna contra el virus del papiloma humano y DPT.', 'Pentavalente, Neumococo conjugada, bOPV.', 'BCG, Rotavirus.', 'C', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'CACES Octubre 2026 - revisión B'),
  ('5718525f-f034-57d4-b243-12607bac464b', 'Usted como profesional de enfermería está programando las visitas domiciliarias en su comunidad y decide priorizar a una familia en la que un adulto mayor convive con sus dos hijas mayores de edad, ha sido diagnosticado con tuberculosis pulmonar y es necesario evaluar el estado de salud de todos los miembros de la familia, asegurar la adherencia al tratamiento y prevenir la transmisión de la enfermedad a otros miembros de la comunidad. Según el Modelo de Atención Integral del Sistema Nacional de Salud Familiar, Comunitaria e Intercultural (MAIS-FCI). ¿Qué criterio se utilizó para establecer la prioridad de esta visita domiciliaria?', 'Criterio demográfico.', 'Criterio socioeconómico.', 'Criterio administrativo.', 'Criterio epidemiológico.', 'D', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'CACES Octubre 2026 - revisión B'),
  ('9daf678c-4df6-58c5-b542-356e150068c0', 'En una comunidad rural, desde hace un año se presenta falta de agua y el funcionamiento del nuevo centro de comercialización de animales domésticos y la feria de productos de la zona. El personal de Técnicos en Atención Primaria de la Salud (TAPS) refieren al director del Centro de Salud, la presencia de ratas, moscas, perros callejeros, olores desagradables en el ambiente y poco interés de los líderes comunitarios por el problema. Al momento los profesionales enfermeros atienden en el domicilio a pacientes con enfermedades gastrointestinales para hidratación oral, las familias desconocen formas de consumo de agua segura y de higiene ambiental. ¿Cuál es la estrategia para el cambio social y de comportamiento?', 'La participación comunitaria.', 'Ambientes saludables.', 'Los distritos saludables.', 'Comunidades saludables.', 'A', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado Familiar, Comunitario e Intercultural', 'CACES Octubre 2026 - revisión B'),
  ('0e4537b7-4d08-5d15-9350-bcc376e802de', 'Durante la higiene de manos con agua y jabón, después de mojar las manos y aplicar jabón suficiente para cubrir toda la superficie, ¿cuál es el siguiente paso?', 'Frotar con movimiento de rotación el pulgar izquierdo.', 'Frotar las palmas de las manos entre sí.', 'Frotar la punta de los dedos.', 'Frotarse el dorso de los dedos de una mano.', 'B', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidado y Procedimientos Clínicos de Enfermería', 'CACES Octubre 2026 - revisión B'),
  ('8fc2e0cb-f265-5699-a804-83e287dd8d8e', 'Una madre acude con su bebé recién nacido a una unidad de atención primaria para administrar la vacuna BCG. ¿Qué tipo de jeringa y aguja debe utilizarse?', '25Gx5/8 (1ml)', '23Gx 1 (1ml)', '27 G x 3/8 (1ml)', '22Gx 1 1/2 (1ml)', 'C', 'Respuesta verificada con la clave explícita de la revisión del simulador CACES de octubre de 2026.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'CACES Octubre 2026 - revisión B')
